
/* Episode 01 full seven-part source-preserving reader.
 * Editing/revision/status metadata remains outside the manuscript body.
 * No new plot, dialogue or explicit text is generated by this script. */
(function(){
"use strict";
var area=document.getElementById("e01-full-reader"),status=document.getElementById("e01-full-progress"),nav=document.getElementById("e01-full-toc"),host=document.getElementById("e01-full-workspace");
if(!area||!status||!nav||!host)return;
var root=location.pathname.indexOf("/four-walls-story-lab/")>=0?"../":"./";
var selected={curiosity:true,tension:true,response:true,contact:true};
var classifiers=[
 {name:"curiosity",re:/reader.only|private reaction|hidden|conceal|jaanta tha|jaanti thi|jaan.bujh|nahi pata|anjaan|apne mann|mann mein|uske mind|soch|curiosity|test tha|deliberat|secret|conscious|kya sach/i},
 {name:"response",re:/saans|warmth|warm|heat|shiver|tingle|heartbeat|breath|nervous|pulse|blush|freeze|tightness|aware|shock|hichki|sensitive|arous/i},
 {name:"contact",re:/physical contact|shoulder se|haath.*(pakd|lag|chhoo)|touch|brush|press|steady|balance|close.contact|contact|proximity/i},
 {name:"tension",re:/nazar|aankh|eyes|dekha|dekh|glance|notice|chup|hesitat|ruk gay|ruki|looked|stare|khamoshi|attention|ek second|awkward|intense|lingering/i}
];
function e(tag,cls,t){var node=document.createElement(tag);if(cls)node.className=cls;if(t!==undefined)node.textContent=t;return node;}
function clean(text){
 return text
   .replace(/^\*\*\[G[1-6]\]\*\*\s*/,"")
   .replace(/^[🟨🟧]\s*/,"")
   .replace(/\*\*([^*]+)\*\*/g,"$1")
   .replace(/(?<!\w)\*([^*\n]+)\*(?!\w)/g,"$1")
   .trim();
}
function addContent(p,sourceText){
 var text=clean(sourceText),segments=text.match(/[^.!?…]+(?:[.!?…]+|$)/g)||[text];
 if(segments.join("")!==text)segments=[text];
 segments.forEach(function(segment){
  var chosen=null;for(var i=0;i<classifiers.length;i++){var x=classifiers[i];if(selected[x.name]&&x.re.test(segment)){chosen=x.name;break;}}
  if(chosen){var s=e("span","key-"+chosen,segment);p.appendChild(s);}else p.appendChild(document.createTextNode(segment));
 });
}
var data=null;
function draw(){
 if(!data)return;
 area.textContent="";nav.textContent="";
 var currentPart="";
 data.parts.forEach(function(chapter,index){
  var section=e("section","e01-full-chapter");section.id="e01-chapter-"+index;
  if(chapter.part!==currentPart){currentPart=chapter.part;var button=e("button","", "Part "+String(Number(currentPart.slice(1))) );button.type="button";button.addEventListener("click",function(){section.scrollIntoView({behavior:"smooth",block:"start"})});nav.appendChild(button);}
  section.appendChild(e("h2","",chapter.title));
  chapter.blocks.forEach(function(b){
   if(!b.text||!b.text.trim())return;
   var p=e("p","e01-full-paragraph");addContent(p,b.text);section.appendChild(p);
  });
  area.appendChild(section);
 });
 status.textContent="Episode 01 · "+data.parts.length+" scenes · "+data.parts.reduce(function(n,c){return n+c.blocks.length;},0)+" source-linked passages. Unabridged narrative content; editorial status and source locators are separate.";
}
host.querySelectorAll("[data-e01-highlight]").forEach(function(input){
 input.addEventListener("change",function(){selected[input.getAttribute("data-e01-highlight")]=input.checked;draw();});
});
var all=host.querySelector("[data-e01-plain]");
if(all)all.addEventListener("click",function(){var turnOn=Object.values(selected).some(function(x){return x;});Object.keys(selected).forEach(function(k){selected[k]=!turnOn;});host.querySelectorAll("[data-e01-highlight]").forEach(function(c){c.checked=selected[c.getAttribute("data-e01-highlight")];});draw();all.textContent=turnOn?"Enable highlights":"Disable highlights";});
fetch(root+"data/stories/e01_all_seven_parts_continuous_reader_v1.json",{cache:"no-store"})
.then(function(r){if(!r.ok)throw Error("HTTP "+r.status);return r.json()})
.then(function(j){
 var lengths={P01:55,P02:226,P03:24,P05:280,P07:232};
 for(var part in lengths){var n=j.parts.filter(function(s){return s.part===part}).reduce(function(acc,s){return acc+s.blocks.length;},0);if(n!==lengths[part])throw Error(part+" source coverage mismatch: "+n);}
 if(j.parts.length!==31)throw Error("Expected 31 completed source scenes");
 data=j;draw();
}).catch(function(err){status.textContent="The complete edition could not load: "+err.message+". Original source chapters remain accessible from the episode archive.";});
})();
